/**
 * Reports on the words of a text, built on the text-stats API.
 *
 * @packageDocumentation
 */

/** A word, lowercased, and how often it occurs. */
export interface WordCount {
	word: string;
	count: number;
}

/** The `count` most frequent words of `text`, most frequent first, and of those as frequent, the first to occur first. */
export declare function topWords(text: string, count: number): WordCount[];

/** The `count` most frequent words of `text`, one `word: count` line each, most frequent first. */
export declare function report(text: string, count: number): string;
